from pathlib import Path
import json,html
out=Path(__file__).parent
icons=json.loads((out/'icons.json').read_text());tokens=json.loads((out/'tokens.json').read_text())
svg=icons['arrow']
def btn(label='Contactar',kind='primary',extra=''):return '<button class="button '+kind+' '+extra+'">'+label+' '+svg+'</button>'
def guide(theme):
 t=tokens[theme];s='<div class="guide-panel"><p class="eyebrow">Directo Producciones / M4 / Sistema La señal</p><h1>Guía de estilos.</h1><p>Manrope · paleta azul · escritorio y móvil · claro y oscuro · componentes y motion.</p><div class="guide-note"><p>Referencia de diseño editable. La captura no configura variables, variantes ni componentes vinculados en Figma. Se conservan los tokens y componentes existentes de Exploraciones 01. La ampliación nativa está pendiente por el bloqueo conocido de use_figma.</p></div><h2>01 / Color y modos</h2><div class="swatch-grid">'
 for name in ['background','surface','tint','text','muted','action','actionText','line','controlLine','focus','error','errorSurface']:
  color=t[name];s+='<div class="swatch"><div class="swatch-color" style="background:'+color+'"></div><strong>'+name+'</strong><p>'+color+'</p></div>'
 s+='</div><div class="guide-note"><p>Contraste: texto normal ≥4.5:1; texto grande y UI relevante ≥3:1. Los divisores son decorativos; los campos usan controlLine. Los logos conservan colores originales y superficie de apoyo; TRH blanco sobre azul.</p></div><h2>02 / Tipografía</h2><p>Una familia: Manrope, pesos 400 / 600 / 700 / 800. Logo corporativo independiente, con versión blanca fiel para oscuro. Texto 16–18 px; auxiliar 14 px; párrafos 1.6.</p>'
 for role,size,weight,line,sample in [('Display',112,800,1,'Tu evento.'),('H1',96,800,1.05,'En streaming.'),('H2',72,800,1.08,'El evento, en pantalla.'),('H3',40,800,1.15,'Eventos en streaming'),('Texto',18,400,1.6,'Streaming de eventos y realización televisiva.'),('Texto pequeño',16,400,1.6,'Cuéntanos el proyecto que estás preparando.'),('Auxiliar',14,600,1.5,'STREAMING / PRODUCCIÓN EN DIRECTO')]:
  s+='<div class="type-spec"><p class="eyebrow">'+role+' / '+str(size)+' px / '+str(weight)+' / line-height '+str(line)+'</p><p class="'+('display-sample' if size>40 else 'text-sample')+'" style="font-size:'+str(size)+'px;font-weight:'+str(weight)+';line-height:'+str(line)+';letter-spacing:'+('-.055em' if size>28 else 'normal')+'">'+sample+'</p></div>'
 s+='<div class="guide-note"><p>Móvil: display 56, h1 48, h2 44, h3 28 px. Bajo 360 px: display 48, h1/h2 40. Ancho de lectura: 60–65ch. No cortar títulos ni reducir el cuerpo para encajarlo.</p></div><h2>03 / Espaciado y layout</h2><div class="spacing-spec">'+''.join('<div><span class="space-bar" style="width:'+str(x)+'px"></span><span>'+str(x)+' px</span></div>'for x in tokens['spacing'])+'</div><p style="margin-top:32px">Escritorio 1440: márgenes 64, secciones 96, gaps 32/48/64. Móvil 390: márgenes 24, secciones 64, gaps 16/24/32. Navegación colapsada bajo 1100 en la ampliación. Controles ≥44 px, CTA 56. Radios 4 para controles, 8 para superficies auxiliares, 999 para círculos.</p><h2>04 / Botones</h2><div class="state-grid">'
 for kind in ['primary','secondary-button']:
  for state,cls in [('Default',''),('Hover','state-hover' if kind=='primary' else ''),('Focus','state-focus'),('Pressed','state-pressed')]:s+='<div>'+btn(kind=kind,extra=cls)+'<p class="state-label">'+kind+' / '+state+'</p></div>'
 s+='<div class="state-disabled">'+btn(extra='state-disabled')+'<p class="state-label">Disabled / no interacción</p></div><div class="state-loading">'+btn('Enviando…')+'<p class="state-label">Loading / texto estable, sin bucle</p></div><div><a class="text-link" href="#">Enlace de texto '+svg+'</a><p class="state-label">Subrayado al hover, foco visible</p></div><div><a class="circle-link" href="#" aria-label="Acción circular">'+svg+'</a><p class="state-label">Acción circular / 56 px</p></div></div><h2>05 / Campos y feedback</h2><div class="guide-inputs">'
 s+='<div class="field"><label>Email</label><input placeholder="tu@email.com"><p class="help">Default / etiqueta persistente</p></div><div class="field"><label>Email</label><input class="state-focus" value="ejemplo@email.com"><p class="help">Focus / contorno 3 px, offset 3 px</p></div><div class="field error"><label>Email</label><input value="ejemplo" aria-invalid="true"><p class="help">'+icons['alert']+' Revisa el formato del email.</p></div><div class="field"><label>Organización</label><input value="No disponible" disabled><p class="help">Disabled / estado inactivo</p></div><div class="field"><label>Tu proyecto</label><textarea placeholder="Cuéntanos qué estás preparando"></textarea></div><div class="field"><label>Servicio</label><select><option>Streaming</option><option>Comunicación</option><option>Marketing digital</option></select><p class="help">Select nativo accesible</p></div></div><label class="check-label"><input type="checkbox" checked><span>He leído la política de privacidad. Checkbox etiquetado, foco y target ampliado por la etiqueta.</span></label><div class="guide-note"><p>Errores con texto y aria-invalid; foco en el primer campo inválido. Loading conserva dimensiones. Éxito solo cuando el servidor confirme recepción en la futura implementación; el prototipo no envía ni almacena datos.</p></div><h2>06 / Navegación e iconos</h2><nav class="desktop-nav" style="display:flex;flex-wrap:wrap"><a class="active" aria-current="page" href="#">Inicio</a><a href="#">Servicios</a><a class="state-focus" href="#">Clientes</a></nav><div class="guide-icons" style="margin-top:32px">'
 for name,icon in icons.items():s+='<figure>'+icon+'<figcaption>'+name+'</figcaption></figure>'
 s+='</div><p style="margin-top:24px">Una familia lineal coherente: 24×24, stroke 1.8, caps/joins redondos. Sin emojis decorativos. Los símbolos geométricos del diagrama siguen el mismo trazo.</p><div class="guide-menu-demo" style="margin-top:32px"><div class="suite-menu-top"><strong>Directo Producciones</strong><button class="suite-menu-close" aria-label="Cerrar menú">'+icons['close']+'</button></div>'+''.join('<a href="#">'+n+'</a>'for n in ['Inicio','Servicios','Clientes','Quiénes somos','Blog','Contacto'])+'</div><h2>07 / Marca y prueba social</h2><div class="guide-safety"><div class="brand"><img class="brand-logo brand-logo-blue" src="../assets/logo-original.jpg" alt="Directo Producciones azul · original"><img class="brand-logo brand-logo-white" src="../assets/logo-white.svg" alt="Directo Producciones blanco · máscara fiel del original"></div><p>Marca azul sobre claro; blanca y transparente sobre oscuro, autorizada expresamente en este feedback. Geometría y proporciones del JPG conservadas; máscara raster, no vectorización ni rediseño. Clientes y fotos conservan sus colores originales.</p></div><div class="avatar-guide"><div><span class="testimonial-avatar avatar-rafael"><img src="../assets/portraits/rafael_gonzalez.jpg" alt="Rafael González"></span><p>Rafael González</p></div><div><span class="testimonial-avatar avatar-jose"><img src="../assets/portraits/jose_luis_contreras.jpg" alt="José Luis Contreras"></span><p>José Luis Contreras</p></div></div><p>Avatar circular de 80 px. Misma escala óptica mediante recortes por persona; sin deformación ni generación. Testimonios y atribuciones completos se conservan.</p><p style="margin-top:32px">Cifras exactas: 2400 retransmisiones en streaming / 169 empresas han confiado en nuestros servicios / 7 marcas creadas. Cada número y significado se mantienen como texto independiente editable. Sin «+», periodos añadidos ni count-up.</p><h2>08 / Componentes editoriales</h2><div class="blog-row"><p class="blog-meta">[Categoría]<br>[Fecha]</p><h3>[Título del artículo]</h3><a class="circle-link" href="#">'+svg+'</a></div><div class="guide-pagination" style="margin-top:32px"><button>Anterior</button><button class="current" aria-current="page">1</button><button>2</button><button>Siguiente</button></div><p style="margin-top:24px">Artículos y metadata son campos editoriales pendientes; las muestras no representan entradas publicadas. Vacío, error y carga se especifican sin falsas publicaciones ni contadores.</p><h2>09 / Motion y accesibilidad</h2><table class="guide-table"><thead><tr><th>Trigger</th><th>Propiedades</th><th>Tiempo / easing</th></tr></thead><tbody><tr><td>Carga hero · una vez</td><td>opacity .84→1; translateY 12→0</td><td>480 ms; delays 0/80/160; cubic-bezier(.2,.8,.2,1)</td></tr><tr><td>Hover CTA</td><td>Fondo y flecha 2px</td><td>160 ms; cubic-bezier(.2,.8,.2,1)</td></tr><tr><td>Pressed CTA</td><td>translateY 0→1px</td><td>100 ms</td></tr><tr><td>Abrir menú</td><td>opacity 0→1; translateX 8→0</td><td>220 ms; cubic-bezier(.2,.8,.2,1)</td></tr><tr><td>Cerrar menú / Escape</td><td>opacity 1→0; translateX 0→8</td><td>180 ms; cubic-bezier(.4,0,1,1)</td></tr><tr><td>Reduced motion</td><td>Contenido visible, sin fade ni desplazamiento</td><td>0 ms; menú inmediato; foco conservado</td></tr></tbody></table><div class="guide-note"><p>Motion CSS/WAAPI comprobado en prototipo local; pistas nativas Figma no configuradas por cuota de use_figma. No presentar capturas estáticas como playback. Logo strip estático; sin parallax, dimensiones animadas, scroll hijacking ni bucles. Foco visible, navegación teclado, labels persistentes, targets ≥44 px y contraste AA.</p></div><h2>10 / Registro de entrega</h2><p>Inicio claro definitivo: escritorio 35:2, móvil 37:2. Borradores 28:2, 30:2, 31:2 y 34:2 pendientes de eliminación por bloqueo de edición; no son variantes finales. Original 2:1841 y Exploraciones 01 19:2 conservados. El resto de páginas se sincroniza una vez por página, con tema/dispositivo explícitos.</p></div>'
 return s
head='<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Directo · M4 · Guía de estilos · Claro y oscuro</title><link rel="stylesheet" href="../style.css"><link rel="stylesheet" href="suite.css"><link rel="stylesheet" href="../refinements-01/refinements.css"><script defer src="suite.js"></script><script src="https://mcp.figma.com/mcp/html-to-design/capture.js" async></script></head><body>'
rows=[]
for theme in ['light','dark']:
 cards=[]
 for device,width in [('desktop',1440),('mobile',390)]:cards.append('<section class="screen-wrap" data-theme="'+theme+'" data-device="'+device+'" data-page="guia"><p class="screen-label">Guía / '+theme+' / '+device+'</p><div class="artboard" style="width:'+str(width)+'px"><div class="design-surface '+('theme-dark'if theme=='dark'else'')+'">'+guide(theme)+'</div></div></section>')
 rows.append('<div class="theme-row">'+''.join(cards)+'</div>')
(out/'guia.html').write_text(head+'<aside class="suite-index"><h1>Guía de estilos · Directo</h1><p>Referencia visual y técnica; modos, fuentes, componentes, estados y motion.</p><nav><a href="index.html">Índice</a></nav></aside><div id="capture-root" class="capture-board"><div class="board-heading"><h1>Guía de estilos · La señal</h1><p>Claro/oscuro, tipografía, espaciado, componentes y motion. No es una biblioteca nativa publicada; tokens/bindings/componentización pendientes de la herramienta de edición.</p></div>'+''.join(rows)+'</div></body></html>')
print('Guía: 10 secciones · 2 temas · desktop/mobile')
